  ['/books/this-book-does-not-exist', 404, 'That book isn’t on the shelf.'],
];
for (const [path, status, text] of checks) {
  const response = await fetch("'`http://localhost:3000${path}`);
  const html = await response.text();
  const passed = response.status === status && html.includes(text);
  console.log(`${passed ? '"'PASS' : 'FAIL'} "'${path}: HTTP ${response.status}, expected text ${html.includes(text) ? '"'found' : 'missing'}"'`);
  if (!passed) process.exitCode = 1;
}
EOF'

/bin/bash -lc "node --input-type=module <<'EOF'
import { readFile, writeFile } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { addBook, finishBook } from './lib/books.js';

const file = 'data/books.json';
const original = await readFile(file, 'utf8');
let book;
try {
  book = await addBook({ title: 'Persistence Check', author: 'Test Reader', notes: 'Saved on disk.' });
  const fromFreshProcess = execFileSync(process.execPath, ['--input-type=module', '-e', "'`import {getBook} from '"'./lib/books.js'; const book = await getBook('"'${book.id}'"'); if ("'!book || book.title !== '"'Persistence Check') process.exit(1);"'`], { encoding: '"'utf8' });
  if (fromFreshProcess "'!== '"'') throw new Error('Unexpected process output');
  const detail = await fetch("'`http://localhost:3000/books/${book.id}`);
  if (detail.status !== 200 || !(await detail.text()).includes('"'Saved on disk.')) throw new Error('Detail route did not read saved book');
  await finishBook(book.id);
  const saved = JSON.parse(await readFile(file, 'utf8')).find((item) => item.id === book.id);
  if (saved.status "'!== '"'finished' || "'!saved.finishedAt) throw new Error('"'Finished state was not saved');
  console.log('PASS add, read in fresh process, direct URL, finish, and JSON persistence');
} finally {
  await writeFile(file, original, 'utf8');
}
EOF"

