/bin/bash -lc "node --input-type=module <<'EOF'
import { readFile, writeFile } from 'node:fs/promises';

const file = 'data/books.json';
const original = await readFile(file, 'utf8');
const base = 'http://localhost:3000';
function actionFields(html) {
  const form = html.match(/<form\\b["'^>]*>(['"\\s\\S]*?)<\\/form>/)?.[1];
  if ("'!form) throw new Error('"'Form was not rendered');
  const values = new FormData();
  for (const match of form.matchAll(/<input\\b["'^>]*type="hidden"[''^>]*>/g)) {
    const tag = match[0];
    const name = tag.match(/name="([''^"]+)"/)?.[1];
    const value = tag.match(/value="([''^"]*)"/)?.[1] ?? '"'';
    if (name) values.append(name, value.replaceAll('&quot;', '\"').replaceAll('&amp;', '&'));
  }
  return values;
}
try {
  const newPage = await (await fetch("'`${base}/books/new`)).text();
  const createData = actionFields(newPage);
  createData.append('"'title', 'HTTP Form Check');
  createData.append('author', 'Test Reader');
  createData.append('notes', 'Created through the actual form action.');
  const created = await fetch("'`${base}/books/new`, { method: '"'POST', body: createData, redirect: 'manual' });
  const location = created.headers.get('location');
  if (created.status "'!== 303 || !location?.startsWith('"'/books/')) throw new Error("'`Create failed: ${created.status} ${location}`);
  const id = location.split('"'/').at(-1);
  const detail = await (await fetch("'`${base}${location}`)).text();
  if (!detail.includes('"'Created through the actual form action.')) throw new Error('Created book not shown');
  const finishData = actionFields(detail);
  const finished = await fetch("'`${base}${location}`, { method: '"'POST', body: finishData, redirect: 'manual' });
  if ("'![200, 303].includes(finished.status)) throw new Error(`Finish failed: ${finished.status}`);
  const saved = JSON.parse(await readFile(file, '"'utf8')).find((item) => item.id === id);
  if (saved?.status "'!== '"'finished' || "'!saved.finishedAt) throw new Error('"'Finish action did not save');
  console.log('PASS actual add form, direct detail route, and finish form');
} finally {
  await writeFile(file, original, 'utf8');
}
EOF"
